def test_http_reads_leave_demo_repository_unchanged(web_server, demo_view):
    before = git(demo_view.repo, "rev-parse", "HEAD")
    status, headers, body = request(web_server, "/api/bootstrap")
    assert status == 200
    assert len(json.loads(body)["commits"]) == 18
    assert git(demo_view.repo, "rev-parse", "HEAD") == before
    assert git(demo_view.repo, "status", "--porcelain") == ""


@pytest.mark.parametrize("command,expected", [
    ("gita --help", "Read-only Gita CLI"),
    ("gita diff v0.2.0 HEAD --brief", "calculate_order_total"),
    ("gita diff HEAD~2 HEAD --filter returns", "returns.py"),
    ("gita show calculate_order_total v0.2.0 HEAD", "shipping: int = 0"),
    ("gita history calculate_order_total --indexed --brief", "renamed"),
    ("gita history v0.2.0 HEAD --brief", "history: ok"),
    ("gita id shipping_cost", "eid1_"),
    ("gita index --status", "scope relay"),
])
def test_cli_executes_real_read_only_commands(demo_view, command, expected):
    result = demo_view.cli(command)
    assert result["exit_code"] == 0, result["output"]
    assert expected in result["output"]
    assert result["truncated"] is False


