def test_cli_post_returns_output_and_does_not_modify_git(web_server, demo_view):
    before = git(demo_view.repo, "rev-parse", "HEAD")
    status, headers, body = request(web_server, "/api/cli", method="POST",
                                    body=json.dumps({"command": "gita id shipping_cost --json"}),
                                    headers={"Content-Type": "application/json"})
    assert status == 200
    result = json.loads(body)
    assert result["exit_code"] == 0
    assert json.loads(result["output"])["results"][0]["eid"].startswith("eid1_")
    assert git(demo_view.repo, "rev-parse", "HEAD") == before
    assert git(demo_view.repo, "status", "--porcelain") == ""


@pytest.mark.parametrize("body", ['null', '[]', '{}', '{"command": null}', '{"command": "gita", "repo": "/etc"}', 'broken', 'x' * 8193])
def test_cli_post_rejects_malformed_bodies(web_server, body):
    assert request(web_server, "/api/cli", method="POST", body=body,
                   headers={"Content-Type": "application/json"})[0] == 400


def test_cli_post_rejects_cross_origin_and_foreign_host(web_server):
    body = json.dumps({"command": "gita --help"})
    assert request(web_server, "/api/cli", method="POST", body=body,
                   headers={"Content-Type": "application/json", "Sec-Fetch-Site": "cross-site"})[0] == 403
    assert request(web_server, "/api/cli", host="foreign.example", method="POST", body=body,
                   headers={"Content-Type": "application/json"})[0] == 403